import{_ as s,C as o,c as n,o as l,aj as h,j as t,G as r,a as g,w as p}from"./chunks/framework.Bfdr4H5E.js";const c="/sk/images/Enter-Aggressively-with-mkt.webp",d="/sk/images/Equity-Market-Share.webp",u="/sk/images/Forex-Market-Share.webp",x=JSON.parse('{"title":"Price Action","description":"","frontmatter":{"outline":"deep","prev":{"text":"Collective Market Sentiment","link":"/trading-with-pav/collective-market-sentiment"},"next":{"text":"Indicators – Use or Not","link":"/trading-with-pav/indicators-use-or-not"}},"headers":[],"relativePath":"trading-with-pav/price-action.md","filePath":"trading-with-pav/price-action.md"}'),m={name:"trading-with-pav/price-action.md"};function w(y,e,f,b,v,k){const i=o("GraphComment"),a=o("ClientOnly");return l(),n("div",null,[e[0]||(e[0]=h('<h1 id="price-action" tabindex="-1">Price Action <a class="header-anchor" href="#price-action" aria-label="Permalink to &quot;Price Action&quot;">​</a></h1><p>In this new <strong>Module 2 : PRICE ACTION &amp; S/R</strong> first we gonna take a look at Price Action which is the foundation of trading analysis first step into understanding the charts so lets get into it.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#price-action-1">Price Action</a></li><li><a href="#why-does-the-price-move">Why Does the Price Move ?</a><ul><li><a href="#example-of-why-does-the-price-move">Example of Why Does the Price Move ?</a></li><li><a href="#key-points-to-remember">Key Points to Remember</a></li></ul></li><li><a href="#who-moves-the-price">Who Moves the Price ?</a></li><li><a href="#how-to-be-profitable">How to Be Profitable ?</a></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="price-action-1" tabindex="-1">Price Action <a class="header-anchor" href="#price-action-1" aria-label="Permalink to &quot;Price Action&quot;">​</a></h2><p>Price Action is the art of understanding the naked charts without any indicators. It is the first thing we recommend to learn before jumping into anything else. The thing is that we don’t look for candlestick formations.</p><p>If we compared Price Action to reading, then candlestick formations would be only single letters or single words. However, price charts and markets speak in sentences; not single separate letters or words.</p><p>For that reason, we perceive the price movement as a continuous flow and the main thing we are interested in is the price dynamics.</p><h2 id="why-does-the-price-move" tabindex="-1">Why Does the <strong>Price</strong> Move ? <a class="header-anchor" href="#why-does-the-price-move" aria-label="Permalink to &quot;Why Does the **Price** Move ?&quot;">​</a></h2><p>As we already learnt in previous <strong>Volume 1: INTRODUCTION</strong> that prices move up or down due to <strong>market orders</strong>. So in context of Price Action what truly moves the price is <strong>AGGRESSION</strong>.</p><ol><li>If the price goes <strong>up</strong>, <ul><li>then the <strong>buyers</strong> are more <strong>aggressive</strong>.</li></ul></li><li>If it goes <strong>down</strong>, <ul><li>then <strong>sellers</strong> are more <strong>aggressive</strong>.</li></ul></li><li>If you are <strong>aggressive</strong>, <ul><li>you want to <strong>buy</strong> or <strong>sell</strong> <strong>NOW</strong>.</li></ul></li><li>If you want something <strong>NOW</strong> and you want to be 100 % sure you will get it, <ul><li>you need to use <strong>MARKET ORDER</strong>.</li></ul></li></ol><p>This type of order means that whatever the price is, your order will get filled. In other words: you place a <strong>MARKET ORDER</strong> to buy or sell <strong>immediately at the best available current price</strong>.</p><h3 id="example-of-why-does-the-price-move" tabindex="-1">Example of Why Does the <strong>Price</strong> Move ? <a class="header-anchor" href="#example-of-why-does-the-price-move" aria-label="Permalink to &quot;Example of Why Does the **Price** Move ?&quot;">​</a></h3><p>Imagine a situation when there is a piece of news that implies that IDFC FIRST BANK will go up. You are a hedge fund trader, and you want to enter a long position with 1,00,000 shares at 43.25 (that equals to INR 4,325,000).</p><p>Unfortunately, everybody else sees this piece of news, and they also see the opportunity.</p><p>The price is starting to go up rapidly. You want to be part of this, and you really want to enter your position. However, this is happening too fast.</p><p>To make sure you will be able to jump into the new trend, you need to enter the trade with <strong>MARKET ORDER</strong>. You need to be <strong>aggressive</strong>.</p><p><img src="'+c+'" alt="Enter-Aggressively-with-mkt"></p><p>Because your position is pretty big, it won’t be filled all at once. It will get filled fast, you will<br> be able to enter the whole position, but the position will get split as the price moves upward<br> quickly.</p><p>As you can see in the above image the first 10,000 shares were distributed from ₹ 43.30 to ₹ 43.55 then next 20,000 shares were distributed from ₹ 43.55 to ₹ 43.65. The 40,000 shares made a huge long upper wick spreading shares from ₹ 43.65 to ₹ 43.80. Next 20,000 shares were also in that same vicinity and the last 10,000 shares ₹ 43.75 to ₹ 43.80.</p><p>So when all the orders were going through Market Order you can see a trend started in upward direction and after orders completed it came down putting the position in risk.</p><h3 id="key-points-to-remember" tabindex="-1">Key Points to Remember <a class="header-anchor" href="#key-points-to-remember" aria-label="Permalink to &quot;Key Points to Remember&quot;">​</a></h3><ul><li>It is the <strong>aggressive market participants</strong>, who drive the price <strong>aggressively up</strong> or <strong>down</strong> with their <strong>market orders</strong>.</li><li><strong>This is the true reason why the price moves.</strong></li><li><strong>Remember: it is the aggressive buyers/sellers with their aggressive market orders who drive the price up or down.</strong></li></ul><h2 id="who-moves-the-price" tabindex="-1">Who Moves the Price ? <a class="header-anchor" href="#who-moves-the-price" aria-label="Permalink to &quot;Who Moves the Price ?&quot;">​</a></h2><p><img src="'+d+'" alt="Equity-Market-Share"></p><ul><li>The table above shows that roughly 83.4% of all the equity volume is transacted by the big financial institutions.</li><li>They have the <strong>absolute majority</strong>, they <strong>move</strong> and <strong>manipulate the price</strong>. It is their game!</li><li>On the other hand at the bottom of the picture, you can see a small share of 8% that the retail traders own (that’s us).</li><li>It is not just the Equity market. It is the same for all trading instruments.</li><li>If you look for example at the forex market, you can see that it is identical.</li></ul><p><img src="'+u+'" alt="Forex-Market-Share"></p><ul><li>The table above shows that roughly 63.66% of all the currency volume is transacted by the big financial institutions as of 2020.</li><li>The Market is always moved, dominated, and manipulated by a few big institutions or financial groups.</li><li>As you can see, you and I are pretty small.</li><li><strong>We can’t move</strong> the <strong>price,</strong> <strong>we can’t manipulate</strong> the <strong>markets</strong>, BUT <strong>we can be</strong> <strong>profitable!</strong></li></ul><h2 id="how-to-be-profitable" tabindex="-1">How to Be Profitable ? <a class="header-anchor" href="#how-to-be-profitable" aria-label="Permalink to &quot;How to Be Profitable ?&quot;">​</a></h2><ul><li><p>So to be profitable! We only need to accept our role in this <strong>game</strong>, i.e. we need to keep an eye on <strong>the big guys – the institutions</strong>.</p></li><li><p><strong>How</strong> do we do that? How do we <strong>track institutions</strong>?</p></li><li><p>We track them through <strong>PRICE ACTION</strong> and <strong>VOLUMES</strong>.</p></li><li><p><strong>PRICE ACTION</strong> &amp; <strong>VOLUMES</strong> provide us with clues on:</p><ul><li><strong>what</strong> the <strong>institutions were doing</strong> ?</li><li><strong>what</strong> they are <strong>doing right now</strong> ? &amp;</li><li><strong>what</strong> they most likely will be <strong>doing in the future</strong> ?</li></ul></li></ul><p>That’s it for this article in next one we explore How to Spot Institutional Activity With PRICE ACTION ?</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',31)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/wB2VxJS4r_k",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[g("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),r(a,null,{default:p(()=>[r(i)]),_:1})])}const I=s(m,[["render",w]]);export{x as __pageData,I as default};
